#include <iostream>
#include <algorithm>
#include <vector>
#include <functional>

int main() {
    std::vector<int> coll = {9, 8, 7, 6, 5, 4, 3, 2, 1};
    std::cout << "initialized: ";
    for (int i : coll) std::cout << i << ' ';
    std::cout << std::endl;

    // Transform using a lambda (modern functor equivalent)
    std::transform(coll.begin(), coll.end(), coll.begin(), [](int x) { return x * 10; });  // Lambda as inline functor
    std::cout << "transformed: ";
    for (int i : coll) std::cout << i << ' ';
    std::cout << std::endl;

    // Replace using std::bind2nd
    std::replace_if(coll.begin(), coll.end(), std::bind2nd(std::less<int>(), 50), 42);
    std::cout << "replaced: ";
    for (int i : coll) std::cout << i << ' ';
    std::cout << std::endl;

    // Remove using the same binder
    auto it = std::remove_if(coll.begin(), coll.end(), std::bind2nd(std::less<int>(), 40));
    coll.erase(it, coll.end());
    std::cout << "removed: ";
    for (int i : coll) std::cout << i << ' ';
    std::cout << std::endl;

    return 0;
}
